<?php
require __DIR__ . '/functions.php';
$quickAction = $_GET['action'] ?? '';
if ($quickAction === 'add' || $quickAction === 'minus') {
	$quickId = (int)($_GET['id'] ?? 0);
	if ($quickAction === 'add') add_to_cart($quickId);
	if ($quickAction === 'minus') { add_to_cart($quickId, 0); if (isset($_SESSION['cart'][$quickId])) { $_SESSION['cart'][$quickId]--; if ($_SESSION['cart'][$quickId] < 1) remove_from_cart($quickId); } }
	header('Location: index.php?view=cart'); exit;
}
if ($_SERVER['REQUEST_METHOD'] === 'POST') { check_csrf(); $action = $_POST['action'] ?? ''; $id = (int)($_POST['product_id'] ?? 0); if ($action === 'add') add_to_cart($id, (int)($_POST['quantity'] ?? 1)); if ($action === 'remove') remove_from_cart($id); header('Location: index.php?view=cart'); exit; }
$view = $_GET['view'] ?? 'shop'; $category = $_GET['category'] ?? ''; $query = $_GET['q'] ?? '';
$statement = db()->prepare('SELECT * FROM products WHERE active = 1 AND (? = "" OR category = ?) AND (name LIKE ? OR description LIKE ?) ORDER BY id DESC'); $like = "%$query%"; $statement->execute([$category, $category, $like, $like]); $products = $statement->fetchAll(); $lines = cart_products(); $subtotal = array_reduce($lines, fn($sum, $line) => $sum + ($line['price'] * $line['quantity']), 0); $delivery = 700; $shipping = $lines ? $delivery : 0;
