<div class="announcement">Free delivery to your Bureau from 10,000 DA &nbsp; • &nbsp; Cash on delivery available</div><header class="header shell"><a class="brand" href="index.php"><img src="assets/logo.jpeg" alt="Lissi"><span>LISSI</span></a><nav class="nav"><a href="index.php">Shop all</a><a href="?category=Women">Women</a><a href="?category=Men">Men</a><a href="?category=Accessories">Accessories</a></nav><a class="bag" href="?view=cart">Bag (<?= cart_count() ?>)</a></header>
<?php if ($view === 'cart'): ?><section class="section shell"><p class="eyebrow">Your selection</p><h2>Your bag</h2><?php if (!$lines): ?><p>Your bag is waiting for something good. <a href="index.php">Continue shopping</a></p><?php else: ?><?php foreach ($lines as $line): ?><div class="line"><div class="art" style="background:<?= e($line['image_color']) ?>"><strong><?= e($line['short_name']) ?></strong></div><div><b><?= e($line['name']) ?></b><span><?= money($line['price']) ?></span><div class="step"><a href="?view=cart&action=minus&id=<?= $line['id'] ?>">−</a><span><?= $line['quantity'] ?></span><a href="?view=cart&action=add&id=<?= $line['id'] ?>">+</a><form method="post"><input type="hidden" name="csrf" value="<?= csrf() ?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?= $line['id'] ?>"><button type="submit">Remove</button></form></div></div></div><?php endforeach; ?><div class="summary"><div><span>Subtotal</span><b><?= money($subtotal) ?></b></div><div><span>Delivery</span><b><?= money($shipping) ?></b></div><div class="total"><span>Total</span><b><?= money($subtotal + $shipping) ?></b></div><a class="dark" href="checkout.php">Checkout · COD →</a></div><?php endif; ?></section>
